976	            if let Some(behavior) = registry.get(card_id) {
977	                behavior.on_leave_battlefield(state, object_id, registry);
978	            }
979	        }
980	        PendingTrigger::AttacksTrigger { object_id, card_id, .. } => {
981	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
982	                if let Some(behavior) = registry.get(card_id) {
983	                    behavior.on_attacks(state, object_id, registry);
984	                }
985	            }
986	        }
987	        PendingTrigger::BlocksTrigger { object_id, card_id, blocked_attacker, .. } => {
988	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
989	                if let Some(behavior) = registry.get(card_id) {
990	                    behavior.on_blocks(state, object_id, blocked_attacker, registry);
991	                }
